create or replace function plan_schedule_solve_job_v1(p_mode text default 'QUICK',p_candidate_count smallint default 4,p_compute_preference text default 'AUTO',p_quality_target smallint default 70) returns uuid language plpgsql security definer set search_path=public as $$declare j uuid;ids uuid[];i int;w uuid;begin perform open_permission_context('schedule.generate');if p_candidate_count<1 or p_candidate_count>32 then raise exception 'candidate_count 1..32 olmalıdır';end if;if p_compute_preference not in('AUTO','DB','CPU','GPU','HYBRID') then raise exception 'COMPUTE_PREFERENCE_INVALID';end if;insert into schedule_solve_jobs(mode,candidate_count,compute_preference,quality_target,status) values(p_mode,p_candidate_count,p_compute_preference,p_quality_target,'QUEUED') returning id into j;select array_agg(id order by case worker_type when 'GPU' then 0 when 'CPU' then 1 else 2 end,current_load,priority) into ids from schedule_compute_workers where active and health in('HEALTHY','DEGRADED') and (worker_key='db-native' or last_heartbeat>now()-interval '5 minutes') and (p_compute_preference in('AUTO','HYBRID') or worker_type=p_compute_preference);if coalesce(array_length(ids,1),0)=0 then select array_agg(id) into ids from schedule_compute_workers where worker_key='db-native' and active;end if;if coalesce(array_length(ids,1),0)=0 then raise exception 'NO_COMPUTE_WORKER';end if;for i in 1..p_candidate_count loop w:=ids[((i-1)%array_length(ids,1))+1];insert into schedule_solve_attempts(job_id,worker_id,attempt_no,seed,status,profile_key) values(j,w,i,(extract(epoch from clock_timestamp())::bigint%2147483647+i*7919)::int,'PLANNED',p_compute_preference);end loop;return j;end$$;